interface Footstep {
  x: number;
  y: number;
  progress: number;
  angle: number;
}

export function drawBehavioralAnalytics(
  ctx: CanvasRenderingContext2D,
  canvas: HTMLCanvasElement,
  primaryColor: string,
  footsteps: Footstep[]
): Footstep[] {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Add new footsteps
  if (Math.random() < 0.05) {
    footsteps.push({
      x: Math.random() * canvas.width,
      y: -50,
      progress: 0,
      angle: Math.PI / 4 + ((Math.random() - 0.5) * Math.PI) / 6,
    });
  }

  // Update and draw footsteps
  return footsteps.filter(step => {
    step.progress += 0.01;
    step.y += Math.sin(step.angle) * 3;
    step.x += Math.cos(step.angle) * 3;

    const size = 12;
    const opacity = Math.floor(20 * (1 - step.progress)).toString(16);

    ctx.save();
    ctx.translate(step.x, step.y);
    ctx.rotate(step.angle);

    // Left foot
    ctx.beginPath();
    ctx.ellipse(-5, 0, size / 2, size, 0, 0, Math.PI * 2);
    ctx.fillStyle = `${primaryColor}${opacity}`;
    ctx.fill();

    // Right foot
    ctx.beginPath();
    ctx.ellipse(5, -15, size / 2, size, 0, 0, Math.PI * 2);
    ctx.fillStyle = `${primaryColor}${opacity}`;
    ctx.fill();

    ctx.restore();

    return step.y < canvas.height + 50 && step.progress < 1;
  });
}

export type { Footstep };
