import { motion } from 'framer-motion';
import { DivideIcon as LucideIcon } from 'lucide-react';
import { Link } from 'react-router-dom';

import { normalizeTag } from '../../utils/tagUtils';

interface SkillCardProps {
  title: string;
  description: string;
  icon: typeof LucideIcon;
  onClick: () => void;
  isSelected: boolean;
}

export default function SkillCard({
  title,
  icon: Icon,
  description,
  onClick,
  isSelected,
}: SkillCardProps) {
  const normalizedTag = normalizeTag(title);

  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.95 }}
      onClick={onClick}
      className={`cursor-pointer p-6 rounded-lg transition-all relative z-20 ${
        isSelected
          ? 'bg-primary text-white ring-2 ring-primary ring-offset-2 dark:ring-offset-neutral-darker shadow-lg'
          : 'bg-white/95 dark:bg-neutral-dark/95 hover:bg-primary-light/10 dark:hover:bg-neutral-darker/95 backdrop-blur-md hover:shadow-md'
      }`}
    >
      <div className="flex items-start gap-4">
        <Icon
          className={`w-6 h-6 flex-shrink-0 mt-1 ${
            isSelected ? 'text-white' : 'text-primary dark:text-primary-light'
          }`}
        />
        <div>
          <Link
            to={`/filtered/${normalizedTag}`}
            className={`text-xl font-semibold mb-2 block transition-colors duration-200 ${
              isSelected
                ? 'text-white hover:text-white/90 group-hover:scale-105 transition-transform'
                : 'text-neutral-dark dark:text-white hover:text-primary dark:hover:text-primary-light no-underline hover:no-underline group-hover:scale-105 transition-transform'
            }`}
          >
            {title}
          </Link>
          <p
            className={`text-base leading-relaxed ${
              isSelected ? 'text-white/90' : 'text-neutral-dark/70 dark:text-white/70'
            } transition-colors`}
          >
            {description}
          </p>
        </div>
      </div>
    </motion.div>
  );
}
