import { motion } from 'framer-motion';
import { useEffect, useRef } from 'react';

import { useCanvas } from './useCanvas';
import { drawBehavioralAnalytics, type Footstep } from './visualizations/drawBehavioralAnalytics';
import { drawExecutiveCollaboration, type Node } from './visualizations/drawExecutiveCollaboration';
import { drawExperienceDesign } from './visualizations/drawExperienceDesign';

interface BackgroundVisualizationProps {
  activeCategory: string | null;
}

function initNodes(w: number, h: number): Node[] {
  return Array.from({ length: 20 }, () => ({
    x: Math.random() * w,
    y: Math.random() * h,
    vx: (Math.random() - 0.5) * 0.5,
    vy: (Math.random() - 0.5) * 0.5,
  }));
}

export default function BackgroundVisualization({ activeCategory }: BackgroundVisualizationProps) {
  const { canvasRef, ctx, canvas } = useCanvas();
  const nodesRef = useRef<Node[]>([]);
  const footstepsRef = useRef<Footstep[]>([]);
  const timeRef = useRef(0);

  useEffect(() => {
    if (!ctx || !canvas) return;

    if (!activeCategory) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      return;
    }

    const primaryColor =
      getComputedStyle(document.documentElement).getPropertyValue('--color-primary').trim() ||
      '#0097A7';

    nodesRef.current = initNodes(canvas.width, canvas.height);
    footstepsRef.current = [];
    timeRef.current = 0;

    let isVisible = false;
    let animId: number | undefined;

    const observer = new IntersectionObserver(
      ([entry]) => {
        isVisible = entry.isIntersecting;
        if (isVisible && !animId) animId = requestAnimationFrame(animate);
        else if (!isVisible && animId) {
          cancelAnimationFrame(animId);
          animId = undefined;
        }
      },
      { threshold: 0.01 }
    );
    observer.observe(canvas);

    function animate() {
      if (!isVisible || !ctx || !canvas) {
        animId = undefined;
        return;
      }
      timeRef.current += 0.01;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      switch (activeCategory) {
        case 'Experience Design':
          drawExperienceDesign(ctx, canvas, primaryColor, timeRef.current);
          break;
        case 'Behavioural Analytics':
          footstepsRef.current = drawBehavioralAnalytics(
            ctx,
            canvas,
            primaryColor,
            footstepsRef.current
          );
          break;
        case 'Executive Collaboration':
          drawExecutiveCollaboration(ctx, canvas, primaryColor, nodesRef.current);
          break;
      }
      animId = requestAnimationFrame(animate);
    }

    animId = requestAnimationFrame(animate);
    return () => {
      observer.disconnect();
      if (animId) cancelAnimationFrame(animId);
    };
  }, [activeCategory, ctx, canvas]);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 w-full h-full pointer-events-none overflow-hidden"
      style={{ zIndex: -1 }}
    >
      <canvas
        ref={canvasRef}
        className="absolute inset-0 w-full h-full opacity-[0.15]"
        style={{ transform: 'translate3d(0,0,0)', backfaceVisibility: 'hidden' }}
      />
    </motion.div>
  );
}
