import { motion, AnimatePresence } from 'framer-motion';
import { ChevronDown } from 'lucide-react';
import { createElement, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

import { getIconComponent } from '../../utils/iconMap';

interface SkillSectionProps {
  title: string;
  description: string;
  icon: string;
  isExpanded: boolean;
  onToggle(): void;
  children: React.ReactNode;
}

export default function SkillSection({
  title,
  description,
  icon,
  isExpanded,
  onToggle,
  children,
}: SkillSectionProps) {
  const sectionRef = useRef<HTMLDivElement>(null);

  const scrollToSection = () => {
    if (!sectionRef.current) return;

    // Get header height (88px) plus extra padding for visual comfort
    const offset = 112; // 88px header + 24px padding

    const element = sectionRef.current;
    const elementTop = element.getBoundingClientRect().top;
    const offsetPosition = elementTop + window.scrollY - offset;

    window.scrollTo({
      top: Math.max(0, offsetPosition),
      behavior: 'smooth',
    });
  };

  useEffect(() => {
    if (isExpanded) {
      // Scroll after a brief delay to ensure DOM updates
      requestAnimationFrame(scrollToSection);
    }
  }, [isExpanded]);

  return (
    <motion.div
      ref={sectionRef}
      id={`skill-section-${title.toLowerCase().replace(/\s+/g, '-')}`}
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4 }}
      className="bg-white/95 dark:bg-neutral-dark/95 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden relative z-20 scroll-mt-[112px]"
    >
      <motion.button
        onClick={onToggle}
        className="w-full p-8 text-left hover:bg-white/50 dark:hover:bg-neutral-darker/50 transition-all duration-300"
        whileHover={{ scale: 1.01 }}
        whileTap={{ scale: 0.99 }}
      >
        <div className="flex items-center justify-between">
          <motion.div
            className="flex items-center gap-4"
            animate={{
              x: isExpanded ? 0 : -10,
              opacity: isExpanded ? 1 : 0.8,
            }}
            transition={{ duration: 0.3 }}
          >
            <motion.div
              animate={{
                rotate: isExpanded ? 360 : 0,
                scale: isExpanded ? 1.1 : 1,
              }}
              transition={{ duration: 0.5 }}
            >
              {createElement(getIconComponent(icon), {
                className: 'w-8 h-8 text-primary dark:text-primary-light flex-shrink-0',
              })}
            </motion.div>
            <h2 className="text-2xl md:text-3xl font-bold text-neutral-dark dark:text-white font-title tracking-[-0.04em] uppercase">
              {title}
            </h2>
          </motion.div>
          <motion.div
            animate={{
              rotate: isExpanded ? 180 : 0,
              scale: isExpanded ? 1.2 : 1,
            }}
            transition={{ duration: 0.3 }}
            className="ml-4"
          >
            <ChevronDown className="w-6 h-6 text-primary dark:text-primary-light" />
          </motion.div>
        </div>

        <AnimatePresence>
          {isExpanded && (
            <motion.div
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3, delay: 0.1 }}
              className="mt-4 text-base leading-relaxed text-neutral-dark/70 dark:text-white/70 ml-12 prose prose-base dark:prose-invert max-w-none prose-p:m-0 prose-p:text-base prose-p:leading-relaxed prose-strong:text-neutral-dark dark:prose-strong:text-white prose-em:text-neutral-dark dark:prose-em:text-white prose-a:text-primary dark:prose-a:text-primary-light prose-a:no-underline hover:prose-a:underline"
            >
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{description}</ReactMarkdown>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>

      <AnimatePresence initial={false}>
        {isExpanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{
              height: 'auto',
              opacity: 1,
              transition: {
                height: { duration: 0.4 },
                opacity: { duration: 0.3, delay: 0.1 },
              },
            }}
            exit={{
              height: 0,
              opacity: 0,
              transition: {
                height: { duration: 0.3 },
                opacity: { duration: 0.2 },
              },
            }}
            className="overflow-hidden"
          >
            <motion.div
              initial={{ y: 20 }}
              animate={{ y: 0 }}
              transition={{ duration: 0.3 }}
              className="p-8 bg-white/95 dark:bg-neutral-dark/95 backdrop-blur-lg"
            >
              {children}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
