import { motion } from 'framer-motion';

import { useHero } from '../../hooks/useHero';
import { HeroSkeleton } from '../common/HeroSkeleton';

export default function HeroSection() {
  const { hero, isLoading, error } = useHero();

  if (isLoading) {
    return <HeroSkeleton />;
  }

  if (error || !hero) {
    return null;
  }

  // Split the heading into parts to apply different letter spacing
  const [rewi, re] = hero.heading.split('.');
  const [rew, i] = [rewi.slice(0, -1), rewi.slice(-1)];

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      className="text-center mb-16 pt-16"
    >
      <div className="flex flex-col items-center gap-8 mb-12">
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{
            duration: 0.8,
            ease: [0.4, 0, 0.2, 1],
          }}
          className="relative w-48 h-48"
        >
          <motion.div
            animate={{
              rotateZ: [0, 1.5, 0, -1.5, 0],
              y: [0, -3, 0, -3, 0],
            }}
            transition={{
              duration: 6,
              ease: 'easeInOut',
              repeat: Infinity,
              times: [0, 0.25, 0.5, 0.75, 1],
            }}
            className="relative w-full h-full"
          >
            <img
              src="https://dhqvfqbjomlbupcfatxz.supabase.co/storage/v1/object/public/images/images/logo.png"
              alt="REWI.RE Logo"
              className="w-full h-full object-contain drop-shadow-xl"
              width={192}
              height={192}
              decoding="async"
            />
          </motion.div>
        </motion.div>

        <motion.h2
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="text-2xl md:text-3xl lg:text-[4rem] font-bold text-neutral-dark dark:text-white leading-[1.1] text-center font-title uppercase"
        >
          <span className="tracking-[-0.04em]">{rew}</span>
          <span className="tracking-[-0.25em]">{i}</span>
          <span className="tracking-[-0.20em] text-primary dark:text-primary-light">.</span>
          <span className="tracking-[-0.04em]">{re}</span>
        </motion.h2>
      </div>

      <motion.p
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.5 }}
        className="text-2xl font-medium leading-tight text-neutral-dark dark:text-white max-w-4xl mx-auto font-sans"
      >
        {hero.subheading}
      </motion.p>
    </motion.div>
  );
}
