import { useState, useEffect } from 'react';

import { supabase } from '../lib/supabase/client';
import type { SkillCategory } from '../types/skills';
import { getIconComponent } from '../utils/iconMap';

export function useSkills() {
  const [categories, setCategories] = useState<SkillCategory[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    async function fetchSkills() {
      try {
        setIsLoading(true);

        // Fetch categories with their skills, ordered by display_order
        const { data: categoriesData, error: categoriesError } = await supabase
          .from('skill_categories')
          .select(
            `
            id,
            name,
            description,
            icon,
            skills!skills_category_id_fkey (
              id,
              title,
              description,
              icon,
              display_order
            )
          `
          )
          .order('display_order', { ascending: true });

        if (categoriesError) throw categoriesError;
        if (!categoriesData) throw new Error('No data returned');

        // Transform and sort skills within each category
        const transformedCategories: SkillCategory[] = categoriesData.map(category => ({
          id: category.id,
          name: category.name,
          description: category.description,
          icon: category.icon,
          skills: (category.skills || [])
            .sort((a, b) => (a.display_order || 999) - (b.display_order || 999))
            .map(skill => ({
              id: skill.id,
              title: skill.title,
              description: skill.description,
              icon: getIconComponent(skill.icon),
            })),
        }));

        setCategories(transformedCategories);
      } catch (err) {
        setError(err instanceof Error ? err : new Error('Failed to fetch skills'));
        console.error('Error fetching skills:', err);
      } finally {
        setIsLoading(false);
      }
    }

    fetchSkills();
  }, []);

  return { categories, isLoading, error };
}
