import { useState, useEffect } from 'react';

import { useSkills } from '../../hooks/useSkills';
import BackgroundVisualization from '../Background/BackgroundVisualization';
import LoadingSpinner from '../common/LoadingSpinner';

import HeroSection from './HeroSection';
import SkillList from './SkillList';
import SkillSection from './SkillSection';

const CYCLE_INTERVAL = 5000; // 5 seconds

export default function Skills() {
  const { categories, isLoading, error } = useSkills();
  const [expandedCategoryId, setExpandedCategoryId] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [selectedSkills, setSelectedSkills] = useState<{ [key: string]: string | null }>({});
  const [cycleIndexes, setCycleIndexes] = useState<{ [key: string]: number | null }>({});

  // Handle category toggle with sequential closing/opening
  // Initialize cycling for newly expanded category
  useEffect(() => {
    if (!expandedCategoryId) return;

    const category = categories.find(c => c.id === expandedCategoryId);
    if (!category || !category.skills.length) return;

    if (!cycleIndexes[expandedCategoryId]) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- one-time seed when a category first expands
      setCycleIndexes(prev => ({ ...prev, [expandedCategoryId]: 0 }));
      setSelectedSkills(prev => ({
        ...prev,
        [expandedCategoryId]: category.skills[0]?.title || null,
      }));
    }
  }, [expandedCategoryId, categories]);

  // Handle auto-cycling of skills
  useEffect(() => {
    if (!expandedCategoryId) return;

    const category = categories.find(c => c.id === expandedCategoryId);
    if (!category || !category.skills.length) return;

    const interval = setInterval(() => {
      const currentIndex = cycleIndexes[expandedCategoryId] || 0;
      const nextIndex = (currentIndex + 1) % category.skills.length;

      setCycleIndexes(prev => ({
        ...prev,
        [expandedCategoryId]: nextIndex as number,
      }));
      setSelectedSkills(prev => ({
        ...prev,
        [expandedCategoryId]: category.skills[nextIndex]?.title || null,
      }));
    }, CYCLE_INTERVAL);

    return () => clearInterval(interval);
  }, [expandedCategoryId, categories, cycleIndexes]);

  if (isLoading) {
    return <LoadingSpinner />;
  }

  if (error) {
    return (
      <div className="py-20 bg-gray-50 dark:bg-neutral-darker">
        <div className="container mx-auto px-6">
          <div className="text-center">
            <p className="text-neutral-dark/70 dark:text-white/70">
              Failed to load skills: {error.message}
            </p>
          </div>
        </div>
      </div>
    );
  }

  const handleCategoryToggle = (categoryId: string) => {
    if (expandedCategoryId === categoryId) {
      // Just close current category
      setExpandedCategoryId(null);
      setActiveCategory(null);
      setCycleIndexes({});
      setSelectedSkills({});
    } else {
      // First close current category (if any)
      if (expandedCategoryId) {
        setExpandedCategoryId(null);
        setActiveCategory(null);
        setCycleIndexes({});
        setSelectedSkills({});

        // Wait for close animation, then open new category
        setTimeout(() => {
          setExpandedCategoryId(categoryId);
          const category = categories.find(c => c.id === categoryId);
          setActiveCategory(category ? category.name : null);
        }, 300); // Match animation duration
      } else {
        // No category is open, just open the new one
        setExpandedCategoryId(categoryId);
        const category = categories.find(c => c.id === categoryId);
        setActiveCategory(category ? category.name : null);
      }
    }
  };

  const handleSkillSelect = (categoryId: string, skillTitle: string) => {
    // Reset cycling when manually selecting a skill
    setCycleIndexes(prev => ({ ...prev, [categoryId]: null }));
    setSelectedSkills(prev => ({
      ...prev,
      [categoryId]: prev[categoryId] === skillTitle ? null : skillTitle,
    }));
  };

  return (
    <section
      id="skills"
      className="relative py-20 bg-gray-50/95 dark:bg-neutral-darker/95 scroll-mt-24"
    >
      <BackgroundVisualization activeCategory={activeCategory} />
      <div className="container mx-auto px-6 relative z-10">
        <HeroSection />

        <div className="max-w-4xl mx-auto space-y-8">
          {categories.map(category => (
            <SkillSection
              key={category.id}
              title={category.name}
              description={category.description}
              icon={category.icon}
              isExpanded={expandedCategoryId === category.id}
              onToggle={() => handleCategoryToggle(category.id)}
            >
              <SkillList
                skills={category.skills}
                selectedSkill={selectedSkills[category.id] || null}
                onSkillSelect={skillTitle => handleSkillSelect(category.id, skillTitle)}
              />
            </SkillSection>
          ))}
        </div>
      </div>
    </section>
  );
}
