import * as LucideIcons from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

/**
 * Convert kebab-case or lowercase icon names to PascalCase.
 * e.g. "rotate-3d" -> "Rotate3d", "cpu" -> "Cpu", "Route" -> "Route"
 */
function toPascalCase(name: string): string {
  return name
    .split('-')
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

export const getIconComponent = (iconName: string): LucideIcon => {
  // Try exact match first (PascalCase names from DB)
  // eslint-disable-next-line import/namespace -- icon name arrives from CMS data at runtime
  let icon = LucideIcons[iconName as keyof typeof LucideIcons];

  // Fall back to PascalCase conversion (kebab-case or lowercase names)
  if (!icon || typeof icon === 'string' || typeof icon === 'number') {
    const pascalName = toPascalCase(iconName);
    // eslint-disable-next-line import/namespace -- icon name arrives from CMS data at runtime
    icon = LucideIcons[pascalName as keyof typeof LucideIcons];
  }

  if (!icon || typeof icon === 'string' || typeof icon === 'number') {
    console.warn(`Icon ${iconName} not found, falling back to default`);
    return LucideIcons.HelpCircle;
  }
  return icon as LucideIcon;
};
